card_mod.style:
:host { display: block; }
ha-card { width: 216px !important; height: 216px !important; margin: 14px auto 10px; direction: rtl; box-sizing: border-box; border-radius: 50% !important; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; box-shadow: none !important; transition: background .3s, border-color .3s; background: {{ 'color-mix(in srgb, #0A6FD1 24%, var(--card-background-color))' if is_state('switch.pi_hole', 'on') else 'var(--card-background-color)' }} !important; border: 6px solid {{ '#0A6FD1' if is_state('switch.pi_hole', 'on') else 'var(--divider-color)' }} !important; --ha-tile-info-primary-font-size: 30px; --ha-tile-info-primary-font-weight: 600; --ha-tile-info-primary-line-height: 38px; --ha-tile-info-secondary-font-size: 13px; }
ha-tile-icon { --tile-icon-size: 64px; --mdc-icon-size: 36px; }

ha-card { background: none !important; border: none !important; box-shadow: none !important; border-radius: 0 !important; position: relative; direction: rtl; }
ha-card { border-bottom: 1px solid var(--divider-color) !important; }
ha-card { padding-inline-end: 40px; }
ha-card::after { content: ''; position: absolute; inset-inline-end: 12px; top: 50%; width: 9px; height: 9px; margin-top: -5px; pointer-events: none; border-top: 2px solid var(--secondary-text-color); border-left: 2px solid var(--secondary-text-color); transform: rotate(-45deg); }

